t.script:
//
(function () {
    var orderSelect = document.querySelector('[name="sale_order_id"]');
    var linesSection = document.getElementById('section_order_lines');
    var linesContainer = document.getElementById('order_lines_container');
    var formContinuation = document.getElementById('rma_form_continuation');
    var reasonSelect = document.querySelector('[name="reza_reason_id"]');
    var deadlineHint = document.getElementById('order_deadline_hint');
    var defaultWindow = deadlineHint ? deadlineHint.getAttribute('data-default-window') : '30';
    var exchangeSection = document.getElementById('section_exchange');
    var outcomeRadios = document.querySelectorAll('[name="reza_operation_type"]');

    function escHtml(str) {
        return String(str)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function toggleExchange() {
        var selected = document.querySelector('[name="reza_operation_type"]:checked');
        if (exchangeSection) {
            exchangeSection.style.display = (selected && selected.value === 'exchange') ? 'block' : 'none';
        }
    }

    outcomeRadios.forEach(function(r) {
        r.addEventListener('change', toggleExchange);
    });
    toggleExchange();

    function fetchOrderLines(orderId) {
        if (!orderId) {
            linesSection.style.display = 'none';
            linesContainer.innerHTML = '';
            formContinuation.style.display = '';
            if (deadlineHint) {
                deadlineHint.textContent = 'Standard return window: ' + defaultWindow + ' days from purchase.';
            }
            return;
        }
        linesContainer.innerHTML = '<p class="text-muted">Loading items…</p>';
        linesSection.style.display = 'block';
        if (deadlineHint && orderSelect) {
            var selectedOption = orderSelect.options[orderSelect.selectedIndex];
            var deadline = selectedOption ? selectedOption.getAttribute('data-deadline') : '';
            if (deadline) {
                deadlineHint.textContent = 'Return available until ' + deadline + '.';
            }
        }

        fetch('/my/rmas/order_lines', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'X-Requested-With': 'XMLHttpRequest',
            },
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                id: 1,
                params: { order_id: parseInt(orderId, 10) },
            }),
        })
        .then(function (r) { return r.json(); })
        .then(function (data) {
            var lines = (data.result && data.result.lines) ? data.result.lines : [];
            if (!lines.length) {
                linesContainer.innerHTML = '<p class="text-muted">No returnable items found on this order.</p>';
                formContinuation.style.display = '';
                return;
            }
            if (lines.every(function(l) { return l.already_returned || !l.returnable; })) {
                var hasDeliveredItems = lines.some(function(l) { return l.qty_delivered > 0; });
                var unavailableMessage = hasDeliveredItems
                    ? 'All returnable items in this order have already been returned.'
                    : 'There are no delivered items available to return on this order yet.';
                linesContainer.innerHTML = '<div class="alert alert-warning mb-0">' + unavailableMessage + '</div>';
                formContinuation.style.display = 'none';
                return;
            }
            formContinuation.style.display = '';
            var html = '<div class="table-responsive"><table class="table table-sm align-middle">'
                + '<thead><tr>'
                + '<th style="width:2rem;"></th>'
                + '<th>Product</th>'
                + '<th style="width:7rem;">Qty to Return</th>'
                + '</tr></thead><tbody>';

            lines.forEach(function (line) {
                var disabled = (line.already_returned || !line.returnable) ? ' disabled' : '';
                var badge = line.already_returned
                    ? ' <span class="badge bg-secondary ms-1">Already returned</span>'
                    : (!line.returnable ? ' <span class="badge bg-danger ms-1">Not returnable</span>' : '');
                var policyNote = line.returnable || !line.return_policy_note
                    ? ''
                    : '<div class="small text-danger mt-1">' + escHtml(line.return_policy_note) + '</div>';
                var inputName = 'qty_' + line.id;
                var maxQty = line.max_qty || 1;
                html += '<tr>'
                    + '<td><input type="checkbox" class="form-check-input rma-line-check"'
                    + ' name="line_ids" value="' + line.id + '"'
                    + disabled + '></td>'
                    + '<td>' + escHtml(line.product_name) + badge + policyNote + '</td>'
                    + '<td><input type="number" class="form-control form-control-sm"'
                    + ' name="' + inputName + '"'
                    + ' min="0.01" step="0.01" max="' + maxQty + '"'
                    + ' value="' + maxQty + '"'
                    + disabled + '></td>'
                    + '</tr>';
            });

            html += '</tbody></table></div>';
            linesContainer.innerHTML = html;
        })
        .catch(function () {
            linesContainer.innerHTML = '<p class="text-danger">Could not load items. Please refresh and try again.</p>';
        });
    }

    if (orderSelect) {
        orderSelect.addEventListener('change', function () {
            fetchOrderLines(this.value);
        });
        var preSelected = window._rezaRmaSelectedOrderId || orderSelect.value;
        if (preSelected) {
            fetchOrderLines(preSelected);
        }
    }
})();
//
